import streamlit as st
from PIL import Image
import io
import base64

st.title(" ")

# 硬编码的 Base64 图像数据（红色方形）
base64_image = ""

st.header("")
st.code(base64_image, language="text")

st.header(" ")
try:
    # 解码 Base64
    img_data = base64.b64decode(base64_image)
    image = Image.open(io.BytesIO(img_data))
    
    # 显示图像
    st.image(image, use_container_width=False, caption=" ")
    
    
except Exception as e:
    st.error(f"❌ 解析失败: {str(e)}")
